INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'windows'),3,2,'{"it":"Che differenza c’è con `GROUP BY`?","en":"How is it different from `GROUP BY`?"}','[{"it":"Le righe non vengono riunite","en":"Rows are not collapsed"},{"it":"Nessuna","en":"None"},{"it":"È più lento sempre","en":"It is always slower"},{"it":"Non usa aggregazioni","en":"It uses no aggregates"}]',0,'{"it":"Ogni riga ha il suo valore.","en":"Each row gets its own value."}',NULL);
