INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'explain'),2,3,'{"it":"Un indice su `(a, b)` aiuta una query che filtra solo su `b`?","en":"Does an index on `(a, b)` help a query filtering only on `b`?"}','[{"it":"Di solito no","en":"Usually not"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo con LIMIT","en":"Only with LIMIT"},{"it":"Solo con ORDER BY","en":"Only with ORDER BY"}]',0,'{"it":"Conta la colonna più a sinistra.","en":"The leftmost column matters."}',NULL);
