INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'fork'),3,2,'{"it":"Il connettore MySQL di PHP funziona con MariaDB?","en":"Does PHP’s MySQL connector work with MariaDB?"}','[{"it":"Sì, il protocollo è lo stesso","en":"Yes, the protocol is the same"},{"it":"No, serve un driver diverso","en":"No, it needs another driver"},{"it":"Solo in sola lettura","en":"Only read only"},{"it":"Solo su Windows","en":"Only on Windows"}]',0,'{"it":"PDO e mysqli si collegano senza cambiare nulla.","en":"PDO and mysqli connect with no changes."}',NULL);
