INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`data-colore` è un attributo valido","en":"`data-colore` is a valid attribute"},true],[{"it":"`<template>` si vede appena apri la pagina","en":"`<template>` shows as soon as you open the page"},false],[{"it":"Il CSS può leggere gli attributi data","en":"CSS can read data attributes"},true],[{"it":"`data-*` serve solo alle immagini","en":"`data-*` is only for images"},false]],"why":{"it":"Dati nascosti nell’HTML, pronti per CSS e JavaScript.","en":"Data hidden in the HTML, ready for CSS and JavaScript."}}');
