INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<head>","  <title>Fucina</title>","  <meta name=\\"description\\" value=\\"Impara\\">","</head>"],"bug":2,"fix":"  <meta name=\\"description\\" content=\\"Impara\\">","why":{"it":"I `meta` usano `content`, non `value`.","en":"`meta` tags use `content`, not `value`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":".card {\\n  background: ___-gradient(90deg, red, gold);\\n  ___: 0 2px 8px gray;\\n}","gaps":["linear","box-shadow"],"extra":["radial-shadow","shadow","line"],"why":{"it":"Sfumatura lineare e ombra della scatola.","en":"A linear gradient and a box shadow."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un `background` può essere un’immagine","en":"A `background` can be an image"},true],[{"it":"`box-shadow` cambia lo spazio occupato","en":"`box-shadow` changes the space taken up"},false],[{"it":"Una sfumatura può avere più di due colori","en":"A gradient can have more than two colours"},true],[{"it":"`text-shadow` vale per le immagini","en":"`text-shadow` works on images"},false]],"why":{"it":"Le ombre si disegnano sopra: non spostano nulla.","en":"Shadows are painted on top: they move nothing."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["px",{"it":"Fisso","en":"Fixed"}],["%",{"it":"Rispetto al contenitore","en":"Relative to the container"}],["rem",{"it":"Rispetto alla radice","en":"Relative to the root"}],["vw",{"it":"Rispetto allo schermo","en":"Relative to the screen"}],["em",{"it":"Rispetto al testo dell’elemento","en":"Relative to the element’s text"}]],"why":{"it":"Scegli l’unità in base a che cosa deve seguire la misura.","en":"Pick the unit by what the size should follow."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`1rem` di solito vale 16px","en":"`1rem` is usually 16px"},true],[{"it":"`100vw` è tutta la larghezza dello schermo","en":"`100vw` is the full width of the screen"},true],[{"it":"`px` si adatta allo schermo","en":"`px` adapts to the screen"},false],[{"it":"`%` di un’altezza funziona sempre","en":"`%` of a height always works"},false]],"why":{"it":"Una percentuale d’altezza serve un genitore con altezza definita.","en":"A height percentage needs a parent with a defined height."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["a b",{"it":"`b` dentro `a`","en":"`b` inside `a`"}],["a > b",{"it":"`b` figlio diretto","en":"`b` direct child"}],["a + b",{"it":"`b` subito dopo","en":"`b` right after"}],["a ~ b",{"it":"`b` fratelli successivi","en":"`b` following siblings"}],["a, b",{"it":"Sia `a` che `b`","en":"Both `a` and `b`"}]],"why":{"it":"Un simbolo cambia tutto il significato.","en":"One symbol changes the whole meaning."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"a[href___\\"https\\"] { color: green; }\\na[href___\\".pdf\\"] { color: red; }","gaps":["^=","$="],"extra":["*=","~=","=="],"why":{"it":"`^=` per l’inizio, `$=` per la fine.","en":"`^=` for the start, `$=` for the end."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[":hover",{"it":"Mouse sopra","en":"Mouse over"}],[":active",{"it":"Mentre premi","en":"While pressing"}],[":focus",{"it":"Campo attivo","en":"Active field"}],[":disabled",{"it":"Controllo spento","en":"Switched-off control"}],[":checked",{"it":"Casella spuntata","en":"Ticked box"}]],"why":{"it":"Gli stati rendono viva un’interfaccia.","en":"States bring an interface to life."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".btn {","  outline: none;","  padding: 8px;","}"],"bug":1,"fix":"  outline: 3px solid gold;","why":{"it":"Togliere `outline` lascia senza guida chi naviga con la tastiera.","en":"Removing `outline` leaves keyboard users with no guide."}}');
