INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":[".card {","  transform: rotate(45);","}"],"bug":1,"fix":"  transform: rotate(45deg);","why":{"it":"Una rotazione vuole l’unità: `deg`.","en":"A rotation needs its unit: `deg`."}}');
